pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }

    let mut fields = bytes.splitn(3, '|');
    if fields.next() == Some("v:2") && fields.next() == Some("hello") {
        if let Some(name) = fields.next() {
            return Ok(Msg::Hello(name.into()));
        }
    }

    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello|{}", name),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn encode_roundtrip_ping() {
        let encoded = encode(&Msg::Ping);
        assert!(matches!(decode(&encoded), Ok(Msg::Ping)));
    }

    #[test]
    fn encode_roundtrip_hello() {
        let msg = Msg::Hello("Ada|Lovelace".into());
        let encoded = encode(&msg);

        assert_eq!(encoded, "v:2|hello|Ada|Lovelace");
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(name)) if name == "Ada|Lovelace"));
    }

    #[test]
    fn decode_rejects_unknown_input() {
        assert!(decode("pong").is_err());
        assert!(decode("v:1|hello|Ada").is_err());
        assert!(decode("v:2|hello").is_err());
    }
}
